    public static int atBlock(emon.Port.Cells nodes, emon.Port.Cells regions, emon.Port.Cells text, int x0, int y0, int x1, int y1, int a) {
        // A paragraph of page 1 over a box with one inline text of one letter; answers the paragraph's row.
        int p = Model.nodeNew(nodes, Model.nkParagraph(), 0);
        int t = Model.nodeNew(nodes, Model.nkText(), p);
        int ts = emon.Port.cellsLen(text);
        emon.Port.cellsPush(text, a);
        Model.nodeSetText(nodes, t, ts, 1);
        Model.nodeAddRegion(nodes, regions, p, 1, x0, y0, x1, y1);
        Model.nodeAddSrc(nodes, p, Model.srText());
        Model.nodeAddSrc(nodes, t, Model.srText());
        return p;
    }
    public static void testTheModelSaysWhereOcrWonAndChangesNothingElse() {
        emon.Port.Cells nodes = emon.Port.newCells();
        emon.Port.Cells attrs = emon.Port.newCells();
        emon.Port.Cells regions = emon.Port.newCells();
        emon.Port.Cells text = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        emon.Port.Cells ledger = emon.Port.newCells();
        emon.Port.Cells layout = emon.Port.newCells();
        emon.Port.Cells nfw = emon.Port.newCells();
        emon.Port.Cells fv = emon.Port.newCells();
        emon.Port.Cells feats = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        Model.modelInit(nodes, attrs, regions, text, pages, ledger, layout);
        // two paragraphs: the first over words 0 and 1, the second over word 2
        int pa = atBlock(nodes, regions, text, 0, 0, 2000, 1000, 65);
        int pb = atBlock(nodes, regions, text, 0, 2000, 1000, 3000, 66);
        atTword(nfw, feats, et, 0, 0, 0, 1000, 0, 97, 97);
        atTword(nfw, feats, et, 1000, 0, 0, 1000, 0, 98, 98);
        // word 2 sits in the second paragraph's box
        int w2 = atTword(nfw, feats, et, 0, 0, 0, 1000, 0, 99, 99);
        Evidence.wdSet(nfw, w2, 2, 2200);
        Evidence.wdSet(nfw, 2, 4, 2800);
        Player.fvNew(fv, 0, 1, 101, 900, 0);
        Player.fvNew(fv, 0, 1, 101, 900, 0);
        Player.fvNew(fv, 1, 1, 101, 900, 0);
        emon.Testport.assertEq(Arbiter.arTag(nodes, regions, nfw, fv), 0, "nothing was OCR's: nothing is tagged");
        emon.Testport.assertEq(Model.nodeSrc(nodes, pa), Model.srText(), "the first paragraph is as it was");
        emon.Testport.assertEq(Model.nodeSrc(nodes, pb), Model.srText(), "so is the second");
        // now OCR wins the third word
        emon.Port.cellsSet(fv, 17, 4);
        emon.Port.cellsSet(fv, 19, 800);
        emon.Port.cellsSet(fv, 20, 4);
        emon.Testport.assertEq(Arbiter.arTag(nodes, regions, nfw, fv), 1, "one block was tagged");
        emon.Testport.assertEq(Model.nodeSrc(nodes, pa), Model.srText(), "the paragraph OCR did not touch is not changed");
        emon.Testport.assertEq(Model.nodeFlags(nodes, pa), 0, "nor flagged");
        emon.Testport.assertEq(Model.nodeSrc(nodes, pb), Model.srOcr(), "the one OCR read in full is `ocr`, not `text`");
        emon.Testport.assertEq(Model.nodeFlags(nodes, pb), Model.flTextLayerSuspect(), "flagged text-layer-suspect");
        emon.Testport.assertEq(Model.nodeConf(nodes, pb), 800, "at OCR's confidence");
        emon.Testport.assertEq(Model.nodeSrc(nodes, pb + 1), Model.srOcr(), "and its inline follows");
    }
