        emon.Port.cellsSet(gw, Fuserules.agOangle(), 0);
        emon.Port.cellsSet(gw, Fuserules.agOrel(), 3000);
        emon.Testport.assertEq(Fuserules.frNumber(Fuserules.frDecide(gw)), 140, "tall, but on no image");
